@startuml

class Animal {
  +identifier : int
  +name : string
}

class Breed {
  +name : string
}

class Condition {
  +commonName : string
  +scientificName : string
}

class Appointment {
  +startTime : datetime
}

class Person {
  +identifier : int
  +name : string
  +address : string
  +phoneNumber : string
}

class Owner extends Person {}

class Physician extends Person {}

Animal "*" -- "0..1" Owner : is owned by
Animal "*" -- "0..1" Breed : has breed
Animal "1" -- "*" Appointment : is attended
Condition "*" -- "*" Appointment : is detected in
Condition "*" -- "*" Breed : is common to
Appointment "*" -- "1" Physician : has responsible

@enduml

